theorem.raw:
\label{thm:det nu matrix}
If $T\in\mathcal{M}$ and if $p\in\mathcal{M}$ is a projection such that $Tp=pTp,$ so that we may write
$T=\left(\begin{smallmatrix}
A&B\\
0&C
\end{smallmatrix}\right),$
where $A=Tp$ and $C=(1-p)T,$ then
\begin{equation}\label{eq:DeltaT}
\Delta_{\mathcal{M}}(T)=\Delta_{p\mathcal{M}p}(A)^{\tau(p)}\Delta_{(1-p)\mathcal{M}(1-p)}(C)^{\tau(1-p)}
\end{equation}
and
$$\nu_T=\tau(p)\nu_A+\tau(1-p)\nu_C.$$

lemma.raw:
\label{lem:log invertibles}
If $A,B\in\mathcal{M}$ and if $c>0$, then 
\begin{align*}
B\prec\prec A \qquad&\Leftrightarrow\qquad cB\prec\prec cA, \\
B\prec\prec_{\log}A \qquad&\Leftrightarrow\qquad cB\prec\prec_{\log}cA. 
\end{align*}
Furthermore,
if $1\le A,B\in\mathcal{M}$, where $1$ represents the identity operator,
then
\[
B\prec\prec_{\log} A\qquad\Leftrightarrow\qquad \log(B)\prec\prec\log(A).
\]

\label{det convergence} Let $T\in\mathcal{M}$ and let $q_t$,  $\mathcal{D}$ and $\mathcal{D}_n$ be as in Construction \ref{peano}. For every $\lambda\in\mathbb{C},$ and $\varepsilon>0$, we have
\begin{equation}\label{eq:det convergence}
\lim_{n\to\infty}\log\Delta(|{\rm Exp}_{\mathcal{D}_n}(T)-\lambda|^2+\varepsilon)=\int_{\mathbb{C}}\log(|z-\lambda|^2+\varepsilon)d\nu_T(z).
\end{equation}

\label{first exp lemma} Let $p_t\in\mathcal{M},$ $t\in[0,1],$ be an increasing net of projections,
continuous from the right, with $p_0=0$ and $p_1=1$ and let $\mathcal{D}$ be the von Neumann subalgebra generated by $\{p_t\mid t\in[0,1]\}.$ If $T\in\mathcal{M}$ and $Tp_t=p_tTp_t$ for all $t\in[0,1],$ then
\begin{equation}\label{eq:DeltaD'T}
\Delta(T)=\Delta({\rm Exp}_{\mathcal{D}'}(T)).
\end{equation}

\label{comm quasinilpotent}
Let $T\in\mathcal{M}$ and let $\mathcal{D}$ be as in Construction \ref{peano}.
If $T\in\mathcal{D}',$ then $T-{\rm Exp}_{\mathcal{D}}(T)$ is s.o.t.-quasinilpotent.

\label{logmaj another} We have $B\prec\prec_{\log}A$ if and only if for all $t>0$ we have
\begin{equation}\label{eq:logAtBt}
\tau(\log_+(\frac{|B|}{t}))\leq\tau(\log_+(\frac{|A|}{t})).
\end{equation}

